<script>async function loadDash(){const r=await fetch('api/bookings/history.php',{credentials:'include'}),j=await r.json(),a=j.data||[];const count=s=>a.filter(x=>x.status===s).length;stats.innerHTML=`<div class="stat"><span>Total bookings</span><b>${a.length}</b></div><div class="stat"><span>Pending</span><b>${count('Pending')}</b></div><div class="stat"><span>Approved / payment due</span><b>${count('Approved')}</b></div><div class="stat"><span>Confirmed</span><b>${count('Confirmed')}</b></div>`;recent.innerHTML=a.length?`<div class="mini-list">${a.slice(0,4).map(b=>`<div><strong>${b.vehicleName}</strong><span>${b.startDate} → ${b.endDate}</span><em class="badge ${b.status.toLowerCase()}">${b.status}</em></div>`).join('')}</div>`:'<div class="empty-card">No bookings yet. Start by exploring our fleet.</div>'}loadDash()</script>
